require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','accountant']);$bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('INSERT INTO expenses(branch_id,category,title,amount,expense_date,vendor,payment_method,note,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$bid,trim($_POST['category']),trim($_POST['title']),(float)$_POST['amount'],$_POST['expense_date'],trim($_POST['vendor']),$_POST['payment_method'],trim($_POST['note']),user()['id']]);$eid=(int)db()->lastInsertId();audit_log('expense.created','expense',$eid,trim($_POST['title']).' · '.money((float)$_POST['amount']));flash('success','Expense recorded.');redirect('app/expenses.php');}
$rows=query_all('SELECT * FROM expenses WHERE branch_id=? ORDER BY expense_date DESC,id DESC LIMIT 150',[$bid]);$month=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE branch_id=? AND expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);$revenue=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);$largest=query_one("SELECT category,SUM(amount) total FROM expenses WHERE branch_id=? AND expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01') GROUP BY category ORDER BY total DESC LIMIT 1",[$bid]);
$pageTitle='Expenses';include __DIR__.'/../includes/header.php'; ?>
<div class="metric-strip"><div class="metric-box"><small>Month expenses</small><strong><?= money($month) ?></strong></div><div class="metric-box"><small>Month revenue</small><strong><?= money($revenue) ?></strong></div><div class="metric-box"><small>Operating margin*</small><strong><?= $revenue>0?number_format((($revenue-$month)/$revenue)*100,1):0 ?>%</strong></div><div class="metric-box"><small>Largest category</small><strong style="font-size:1rem"><?= e($largest['category']??'—') ?></strong></div></div><p class="text-muted" style="font-size:.65rem">*Simple dashboard margin = current-month recorded revenue minus recorded expenses.</p><div class="page-actions"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#expenseModal"><i class="fa-solid fa-plus me-2"></i>Add expense</button></div>
<div class="table-card"><div class="table-toolbar"><div><strong>Expense ledger</strong><div class="text-muted" style="font-size:.68rem">Operational spending by category</div></div><a class="btn btn-dark btn-sm" href="<?= url('app/reports.php?export=expenses') ?>"><i class="fa-solid fa-file-export me-1"></i>Export CSV</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Title</th><th>Category</th><th>Vendor</th><th>Method</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= format_date($r['expense_date']) ?></td><td><strong><?= e($r['title']) ?></strong><div class="text-muted" style="font-size:.64rem"><?= e($r['note']) ?></div></td><td><?= e($r['category']) ?></td><td><?= e($r['vendor']) ?></td><td><?= e($r['payment_method']) ?></td><td><strong><?= money($r['amount']) ?></strong></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="expenseModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="modal-header"><h5>Add expense</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-6"><label class="form-label">Category</label><select name="category" class="form-select"><option>Rent</option><option>Utilities</option><option>Payroll</option><option>Maintenance</option><option>Supplies</option><option>Marketing</option><option>Other</option></select></div><div class="col-6"><label class="form-label">Date</label><input type="date" name="expense_date" value="<?= date('Y-m-d') ?>" class="form-control" required></div><div class="col-12"><label class="form-label">Title</label><input name="title" class="form-control" required></div><div class="col-6"><label class="form-label">Amount</label><input type="number" step=".01" name="amount" class="form-control" required></div><div class="col-6"><label class="form-label">Vendor</label><input name="vendor" class="form-control"></div><div class="col-12"><label class="form-label">Payment method</label><select name="payment_method" class="form-select"><option>Bank</option><option>Cash</option><option>Card</option><option>Mobile Banking</option></select></div><div class="col-12"><label class="form-label">Note</label><textarea name="note" class="form-control" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save expense</button></div></form></div></div></div>
